"""RPC Book Two, Titles Nine and Ten (Arts. 267-332): liberty and security; property."""

RA9346 = {'t': 'RA 9346 (2006)', 's': 'Prohibits the imposition of the death penalty; reclusion perpetua without eligibility for parole is imposed instead.', 'u': '#/code/ra9346'}
BP22 = {'t': 'Bouncing Checks Law (BP 22)', 's': 'Issuing a check that bounces is punished regardless of deceit or damage; estafa under Art. 315(2)(d) requires deceit and damage. One act may give rise to both.', 'u': ''}
PD1613 = {'t': 'Law on Arson (PD 1613, 1979)', 's': 'Punishes simple arson and its kinds; destructive arson remains in Art. 320 as amended by RA 7659.', 'u': ''}
RA10883 = {'t': 'New Anti-Carnapping Act (RA 10883, 2016)', 's': 'Taking a motor vehicle is carnapping, punished under this special law rather than as theft or robbery.', 'u': '#/code/ra10883'}


def add(n):
    # ------------------------------------------------------------ Title Nine: liberty and security
    n(267, 'Kidnapping and serious illegal detention (as amended by RA 7659): a private individual who kidnaps or detains another, or deprives him of liberty, when (1) the detention lasts more than three days; (2) it is committed simulating public authority; (3) serious physical injuries are inflicted or threats to kill are made; or (4) the person kidnapped is a minor (except when the accused is a parent), a female or a public officer. Death (now reclusion perpetua without parole) when committed to extort ransom, even if none of those circumstances is present; and when the victim is killed or dies, or is raped, or subjected to torture or dehumanizing acts.',
      k=['Offender is a private individual.', 'He kidnaps or detains another, or deprives him of liberty.', 'The detention is illegal.', 'Any of the four circumstances, or the purpose of extorting ransom.'],
      t=['For kidnapping for ransom, actual payment is not required; the purpose is enough.', 'When the victim is killed, raped, tortured or subjected to dehumanizing acts, it is a special complex crime (kidnapping with homicide, rape, etc.) — RA 7659’s last paragraph.', 'If the primary intent was to kill and the detention was only incidental, the crime is murder, not kidnapping.', 'A public officer who detains without legal ground commits arbitrary detention (Art. 124), unless he acts in a private capacity.'],
      d=[{'n': 'People v. Larrañaga', 'c': 'G.R. Nos. 138874-75, February 3, 2004', 'h': 'The abduction and killing of two sisters were special complex crimes of kidnapping and serious illegal detention with homicide and rape under the last paragraph of Art. 267 as amended by RA 7659; where the victim is killed in the course of the detention, the crimes are not complexed under Art. 48 but form one special complex crime.', 'r': 'Kidnapping with homicide and rape.'}],
      i=[RA9346], chk=['more than three days', 'extorting ransom', 'torture or dehumanizing acts'])
    n(268, 'Slight illegal detention: kidnapping or detention without any of the circumstances of Art. 267. A lower penalty applies if the offender voluntarily releases the victim within three days without attaining his purpose and before criminal proceedings begin.', t=['The voluntary release is a privileged mitigating circumstance; all three conditions must be present.'], chk=['within three (3) days'])
    n(269, 'Unlawful arrest: arresting or detaining another to deliver him to the proper authorities, in a case not authorized by law or without reasonable ground.', t=['The purpose is delivery to the authorities; if the purpose is otherwise, the crime is illegal detention.'], chk=['delivering him to the proper authorities'])
    n(270, 'Kidnapping and failure to return a minor: a person entrusted with the custody of a minor who deliberately fails to restore him to his parents or guardians.', t=['The essential element is the deliberate failure to restore the minor; the custody itself may have begun lawfully (e.g., a nanny or a relative).'], chk=['deliberately fail to restore'])
    n(271, 'Inducing a minor to abandon his home, or the home of his parents or guardians; lighter if committed by the father or mother.', chk=['induce a minor to abandon'])
    n(272, 'Slavery: purchasing, selling, kidnapping or detaining a human being to enslave him; heavier if for assigning him to immoral traffic.', t=['Trafficking in persons is now punished more broadly by RA 9208, as amended.'], chk=['enslaving him'])
    n(273, 'Exploitation of child labor: under pretext of reimbursing a debt incurred by the minor’s ascendant, guardian or custodian, retaining the minor in one’s service against his will.', chk=['retain him in his service'])
    n(274, 'Services rendered under compulsion in payment of debts: compelling a debtor to work for the creditor, against his will, as household servant or farm laborer.', chk=['compel the debtor to work for him'])
    n(275, 'Abandonment of persons in danger: failing to help a person found wounded or in danger of dying in an uninhabited place, when one can do so without detriment to oneself; failing to help one’s own victim of an accident; and failing to deliver a child under seven found abandoned to its family or the authorities.', t=['In item 2 the accident must be caused by the offender without fault; if by his fault, see Art. 365 (failure to render aid aggravates reckless imprudence).'], chk=['uninhabited place'])
    n(276, 'Abandoning a minor under seven whose custody is incumbent on the offender; heavier if the child dies or his life is endangered. Parents who relinquish an infant thirty days old or younger to a safe haven are exempt (RA 11767).', chk=['under seven (7) years of age'])
    n(277, 'Abandonment of a minor by the person entrusted with his custody (delivering him to a public institution or others without consent), and indifference of parents (neglecting to educate children as their station and financial condition permit).', chk=['without the consent of the one who entrusted such child'])
    n(278, 'Exploitation of minors: making a child under sixteen perform dangerous feats of balancing, physical strength or contortion; employing children as acrobats or in similar callings; and delivering a child to such persons. The child-labor laws (RA 9231) also apply.', chk=['sixteen (16) years'])
    n(279, 'The penalties for the preceding articles do not prevent the imposition of penalties for other felonies committed.', chk=['shall not prevent'])
    n(280, 'Qualified trespass to dwelling: a private person who enters the dwelling of another against the latter’s will; heavier if by violence or intimidation. Not applicable to entering to prevent serious harm, to render service to humanity or justice, or entering cafes, taverns and public houses while open.',
      k=['Offender is a private person.', 'He enters the dwelling of another.', 'Against the will of the owner (express or implied prohibition).'],
      t=['“Against the will” requires a prohibition; mere lack of consent is not enough, but entering through a closed door at night implies prohibition.', 'A public officer who does this commits violation of domicile (Art. 128).'],
      chk=['enter the dwelling of another against the latter', 'rendering some service to humanity or justice'])
    n(281, 'Other forms of trespass: entering closed premises or fenced estates of another while uninhabited, when the prohibition to enter is manifest and the trespasser has not secured the owner’s permission.', chk=['manifest'])
    n(282, 'Grave threats: threatening another with a wrong amounting to a crime against his person, honor or property or that of his family — (1) with a demand for money or another condition, attained or not; (2) without a condition.',
      t=['Threats in writing or through a middleman get the maximum period.', 'If the threat is made with a weapon in the heat of anger, see Art. 285.'],
      chk=['amounting to a crime'])
    n(283, 'Light threats: threatening a wrong not constituting a crime, with a demand for money or another condition.', t=['Example: threatening to expose a person’s affair unless paid — the wrong (exposure) is not a crime, but the demand makes it light threats (and may be blackmail).'], chk=['not constituting a crime'])
    n(284, 'In cases of grave and light threats, the offender may be required to give bail not to molest the threatened person; or be sentenced to destierro if he fails to give it.', chk=['not to molest'])
    n(285, 'Other light threats: threatening with a weapon or drawing it in a quarrel (not in self-defense); orally threatening in the heat of anger a wrong amounting to a crime when the acts show no intent to carry it out; and threatening a wrong not amounting to a crime without demand.', chk=['threaten another with a weapon'])
    n(286, 'Grave coercion: without authority of law, by violence, threats or intimidation, preventing another from doing something not prohibited by law, or compelling him to do something against his will, right or wrong. Heavier if in violation of the right of suffrage or to compel or prevent a religious act.',
      k=['A person prevented from doing what is lawful, or compelled to do something against his will.', 'By violence, threats or intimidation.', 'Without authority of law.'],
      t=['If the act is punished by another article (e.g., robbery, kidnapping), that article applies; grave coercion is generic.'],
      chk=['without any authority of law', 'right of suffrage'])
    n(287, 'Light coercions: seizing by violence anything belonging to one’s debtor to apply it to the debt; and “any other coercions or unjust vexations” — any human conduct that unjustly annoys or irritates another without violence (unjust vexation).',
      t=['Unjust vexation is the catch-all: the test is whether the act caused annoyance, irritation, torment or distress to the offended party.'], chk=['unjust vexations'])
    n(288, 'Other similar coercions: forcing employees to buy merchandise from the employer, and paying wages in tokens or objects other than legal tender.', chk=['tokens'])
    n(289, 'Using violence or threats to compel or force laborers or employers in organizing, maintaining or preventing coalitions, strikes or lockouts, if the act is not a more serious offense.', chk=['strike of laborers'])
    n(290, 'Discovering secrets by seizing another’s papers or letters and revealing their contents; lower penalty if not revealed. Not applicable to parents and guardians as to minors in their care, or spouses as to each other’s papers.', t=['RA 4200 (Anti-Wiretapping Act) and RA 10173 (Data Privacy Act) separately protect communications and personal data.'], chk=['seize his papers or letters'])
    n(291, 'Revealing secrets with abuse of office: a manager, employee or servant who learns secrets of his principal or master in that capacity and reveals them.', chk=['secrets of his principal or master'])
    n(292, 'Revelation of industrial secrets: a person in charge, employee or workman of a manufacturing or industrial establishment who reveals its secrets to the prejudice of the owner.', chk=['industrial'])

    # ------------------------------------------------------------ Title Ten: property
    n(293, 'Robbery: taking personal property belonging to another, with intent to gain, by means of violence against or intimidation of any person, or using force upon things.',
      k=['Personal property belonging to another.', 'Unlawful taking (apoderamiento).', 'Intent to gain (animus lucrandi), presumed from the unlawful taking.', 'Violence against or intimidation of persons, or force upon things.'],
      t=['The violence or intimidation must be present before or at the time of the taking; violence used afterward to keep the loot may still be robbery if done to effect the taking.', 'Taking a motor vehicle is carnapping (RA 10883).'],
      i=[RA10883], chk=['with intent to gain', 'using force upon anything'])
    n(294, 'Robbery with violence against or intimidation of persons (as amended by RA 7659): graded penalties for (1) robbery with homicide (or rape, intentional mutilation or arson); (2) with serious physical injuries causing insanity, imbecility, impotency or blindness; (3) with other serious physical injuries; (4) with unnecessary violence or injuries beyond what the robbery required; (5) other cases.',
      t=['Robbery with homicide: the intent is to rob, and the killing is by reason or on occasion of it. “Homicide” is used in its generic sense — all killings, including of robbers, merge into one special complex crime.', 'If the original intent was to kill and the taking was an afterthought, the crimes are homicide/murder and theft, separately.'],
      d=[{'n': 'People v. Ebet', 'c': 'G.R. No. 181635, November 15, 2010', 'h': 'In robbery with homicide the original criminal design is robbery and the killing is committed by reason or on occasion of it; “homicide” is used in its generic sense and absorbs all killings and injuries on that occasion.', 'r': 'Elements of robbery with homicide.'}],
      i=[RA9346], chk=['by reason or on occasion of the robbery', 'homicide shall have been committed'])
    n(295, 'Robbery with physical injuries in an uninhabited place or by a band, or with the use of a firearm on a street, road, highway or alley (as amended by RA 12 and RA 373): the offender suffers the maximum period of the penalty for robbery under subdivisions 3, 4 and 5 of Art. 294; the leader of the band, the penalty next higher in degree.', chk=['street, road, highway, or alley'])
    n(296, 'Definition of a band: more than three armed malefactors taking part in a robbery. If any arm used is an unlicensed firearm, all suffer the maximum penalty. Any member of the band present at the robbery is liable as principal for the assaults committed by the band, unless he tried to prevent them.', t=['“More than three” means at least four, all armed.'], chk=['more than three armed malefactors', 'attempted to prevent the same'])
    n(297, 'Attempted or frustrated robbery with homicide: a special complex crime with its own penalty.', t=['The robbery may be attempted or frustrated, but the homicide must be consummated.'], chk=['attempted or frustrated robbery'])
    n(298, 'Execution of deeds by means of violence or intimidation: compelling another, with intent to defraud, to sign, execute or deliver a public instrument or document.', chk=['public instrument or document'])
    n(299, 'Robbery in an inhabited house, public building or edifice devoted to worship, by armed persons, by entering (through an opening not intended for entrance, breaking walls, roofs, floors, doors or windows, using false keys or picklocks, or under pretense of public authority), or, once inside, by breaking locked or sealed furniture or receptacles or taking them away to be broken outside. Penalty depends on value and whether the offenders were armed.',
      t=['The force upon things must be used to enter (or, once inside, to open locked receptacles); breaking out to escape is not this robbery.'], chk=['Through an opening not intended for entrance or egress'])
    n(300, 'Robbery in an inhabited house in an uninhabited place and by a band: maximum period of the penalty.', chk=['uninhabited place and by a band'])
    n(301, 'Definitions: an inhabited house is any shelter, ship or vessel that is the dwelling of one or more persons, even if temporarily absent; dependencies are interior courts, corrals, warehouses and other places contiguous to the building with an interior entrance.', chk=['Inhabited house means'])
    n(302, 'Robbery in an uninhabited place or in a private building by any of the means of force upon things; heavier for mail matter or large cattle.', chk=['uninhabited place or in a building'])
    n(303, 'Robbery of cereals, fruits or firewood in the cases of Arts. 299 and 302: one degree lower.', chk=['cereals, fruits, or firewood'])
    n(304, 'Possession of picklocks or similar tools specially adapted to robbery, without lawful cause; heavier for locksmiths who make them.', chk=['picklocks'])
    n(305, 'False keys: the tools in Art. 304, genuine keys stolen from the owner, and any keys other than those intended by the owner for use in the lock forcibly opened.', chk=['Genuine keys stolen from the owner'])
    n(306, 'Brigandage (as amended by RA 12): more than three armed persons forming a band of robbers to commit robbery in the highway, kidnapping for extortion or ransom, or any other purpose by force and violence. Use of an unlicensed firearm raises a presumption of brigandage.',
      t=['Brigandage is consummated by the formation of the band for those purposes; no robbery need be committed.', 'Compare PD 532 (highway robbery): applies to indiscriminate robbery of travelers; People v. Puno (1993).'],
      chk=['more than three armed persons form a band of robbers'])
    n(307, 'Aiding and abetting a band of brigands: knowingly aiding, abetting or protecting it, giving it information, or acquiring or receiving property taken by it. Aid is presumed knowing unless the contrary is proven.', chk=['aiding, abetting or protecting a band of brigands'])
    n(308, 'Theft: taking personal property of another with intent to gain, without violence, intimidation or force upon things, and without the owner’s consent. Also theft: failing to deliver lost property found to the owner or authorities; damaging another’s property and removing or using the fruits; and entering an enclosed estate or field to hunt, fish or gather fruits without consent.',
      k=['Taking of personal property.', 'Belonging to another.', 'With intent to gain.', 'Without the owner’s consent.', 'Without violence, intimidation or force upon things.'],
      t=['There is no frustrated theft: theft is consummated once the offender has taken the property with intent to gain, even if he could not dispose of it (Valenzuela v. People).', 'The finder who keeps lost property commits theft even without knowing who the owner is.', '“Taking” requires unlawful deprivation of possession; juridical possession received from the owner (e.g., as agent) makes the misappropriation estafa, not theft.'],
      d=[{'n': 'Valenzuela v. People', 'c': 'G.R. No. 160188, June 21, 2007 (En Banc)', 'h': 'Theft is consummated upon the taking of the property with intent to gain; the ability to freely dispose of it is not an element. There is no frustrated theft.', 'r': 'Stages of theft.'}],
      chk=['intent to gain but without violence', 'without the latter', 'lost property'])
    n(309, 'Penalties for theft by value of the thing stolen (adjusted by RA 10951 in 2017).', t=['Use the RA 10951 brackets for crimes committed after it took effect, and also for earlier ones where it is favorable to the accused (Art. 22).'], chk=['value of the thing stolen'])
    n(310, 'Qualified theft (as amended by RA 120 and BP 71): theft punished two degrees higher if committed by a domestic servant, with grave abuse of confidence, or if the property is a motor vehicle, mail matter or large cattle, coconuts from a plantation, fish from a fishpond, or property taken on the occasion of fire, earthquake, typhoon, volcanic eruption or other calamity, vehicular accident or civil disturbance.',
      t=['Grave abuse of confidence requires a relation of trust that facilitated the taking (e.g., a bank teller).', 'Motor vehicles are now covered by the Anti-Carnapping Act (RA 10883) and large cattle by PD 533.'],
      d=[{'n': 'Chua-Burce v. Court of Appeals', 'c': 'G.R. No. 109595, April 27, 2000', 'h': 'A bank cash custodian who received money only in material (physical) possession, the bank keeping juridical possession, could not be convicted of estafa for the missing money; the proper charge was theft (qualified theft).', 'r': 'Material vs. juridical possession — theft or estafa.'}],
      i=[RA10883], chk=['domestic servant', 'grave abuse of confidence'])
    n(311, 'Theft of property of the National Library or National Museum: penalty of arresto mayor or a fine, or both, unless a higher penalty applies under other provisions.', chk=['National Museum'])
    n(312, 'Occupation of real property or usurpation of real rights: taking possession of real property or usurping a real right of another by violence or intimidation; a fine based on the gain is added to the penalty for the violence.', t=['Violence or intimidation is essential; peaceful but unlawful occupation is not this crime (civil remedies or anti-squatting rules apply).'], chk=['real property'])
    n(313, 'Altering boundaries or landmarks of towns, provinces or estates, or any marks intended to designate them.', chk=['boundary marks'])
    n(314, 'Fraudulent insolvency: absconding with one’s property to the prejudice of creditors; heavier if the offender is a merchant.', chk=['abscond with his property'])
    n(315, 'Estafa (swindling), penalties by amount (adjusted by RA 10951). Three groups of means: (1) with unfaithfulness or abuse of confidence — altering the substance, quantity or quality of things delivered; misappropriating or converting money or goods received in trust, on commission, for administration, or under any obligation to deliver or return; taking undue advantage of a signature in blank; (2) by false pretenses or fraudulent acts executed prior to or simultaneously with the fraud — e.g., pretending to possess power, qualifications or property; postdating or issuing a check without funds (par. 2(d)); (3) through other fraudulent means (e.g., inducing another to sign a document by deceit, removing documents from court records).',
      k=['Abuse of confidence (par. 1(b)): money or property received in trust or under an obligation to return; misappropriation or conversion or denial of receipt; prejudice to another; demand (evidence of misappropriation, not an element).', 'Deceit (par. 2): false pretense made before or at the time of the fraud; reliance on it; damage.', 'Par. 2(d): failure to fund the check within three days of notice of dishonor is prima facie evidence of deceit.'],
      t=['Estafa needs damage or prejudice; BP 22 does not. One check may give rise to both offenses.', 'In par. 1(b) the offender must have received juridical possession; if only material possession, the crime is theft (Chua-Burce v. CA).', 'Syndicated estafa (five or more, defrauding the public of funds solicited from the public) is punished by PD 1689.'],
      i=[BP22], chk=['unfaithfulness or abuse of confidence', 'false pretenses or fraudulent acts', 'prima facie evidence of deceit'])
    n(316, 'Other forms of swindling: pretending to be the owner of real property and disposing of it; disposing of encumbered real property as free; wrongfully taking personal property from its lawful possessor (owner’s case); executing a fictitious contract to another’s prejudice; accepting compensation for services not rendered; and selling, mortgaging or encumbering real property given as surety.', chk=['real property'])
    n(317, 'Swindling a minor: taking advantage of a minor’s inexperience or emotions to make him assume an obligation, give a release, or execute a transfer of property right, to his detriment.', chk=['inexperience or emotions or feelings of a minor'])
    n(318, 'Other deceits not covered by the preceding articles; and interpreting dreams, making forecasts, telling fortunes, or taking advantage of public credulity for profit.', chk=['interpret dreams'])
    n(319, 'Removal, sale or pledge of mortgaged property: knowingly removing personal property mortgaged under the Chattel Mortgage Law to another province or city without the mortgagee’s written consent; or selling or pledging it without the mortgagee’s written consent noted on the record of mortgage.', chk=['Chattel Mortgage Law'])
    n(320, 'Destructive arson (as amended by RA 7659): burning one or more buildings or edifices in a single act or several acts; buildings for public use or where people assemble; trains, ships, airplanes or vehicles for transport of persons or property; public buildings or archives; arsenals, factories and the like; and other listed properties. If death results, death (now reclusion perpetua without parole).',
      t=['Arson other than destructive arson is punished under PD 1613.', 'If the intent was to kill and fire was the means, the crime is murder (by means of fire), not arson.'],
      i=[PD1613, RA9346], chk=['shall burn'])
    for a in (321, 322, 323, 324, 325, 326):
        n(a, 'Part of the Code’s original arson provisions (Arts. 321-326-B), superseded by PD 1613 (1979). Learn PD 1613 and Art. 320 as amended by RA 7659 instead.')
    n(327, 'Malicious mischief: deliberately causing damage to another’s property, not falling within arson.', k=['Deliberate damage to another’s property.', 'Not constituting arson.', 'The act of damaging is done for its own sake (hate, revenge, or mere pleasure of destroying).'], t=['If the damage is caused to gain (e.g., destroying to take), the crime may be theft or robbery.'], chk=['deliberately cause to the property of another any damage'])
    n(328, 'Special cases of malicious mischief: causing damage to obstruct public functions; using poisonous or corrosive substances; spreading infection among cattle; damage to public property or works of art.', chk=['obstruct the performance of public functions'])
    n(329, 'Other mischiefs not included in Art. 328, penalized by the value of the damage.', chk=['value of the damage caused'])
    n(330, 'Damage and obstruction to means of communication: damaging railway, telegraph or telephone lines; heavier if it endangers a train.', chk=['railway, telegraph or telephone lines'])
    n(331, 'Destroying or damaging statues, public monuments or paintings.', chk=['public monuments'])
    n(332, 'Absolutory cause: no criminal, only civil, liability for theft, swindling or malicious mischief committed between spouses, ascendants and descendants or relatives by affinity in the same line; a widowed spouse as to property of the deceased spouse not yet passed to another; and brothers and sisters and brothers-in-law and sisters-in-law living together.',
      t=['It covers only theft, swindling (estafa) and malicious mischief — not robbery, not estafa complexed with falsification (Intestate Estate of Gonzales vda. de Carungcong v. People, 2010).', 'Strangers who participate are not exempt.'],
      d=[{'n': 'Intestate Estate of Manolita Gonzales vda. de Carungcong v. People', 'c': 'G.R. No. 181409, February 11, 2010', 'h': 'A son-in-law accused of estafa through falsification against his mother-in-law could not invoke Art. 332: the absolutory cause covers simple estafa, not the complex crime of estafa through falsification of public documents, which also offends public interest. The relationship by affinity survives the death of the spouse for purposes of Art. 332.', 'r': 'Scope of Art. 332.'}],
      chk=['theft, swindling or malicious mischief', 'living together'])
